def longest_common_prefix(words):
 if not words: return ""
 prefix=words[0]
 for word in words[1:]:
  while not word.startswith(prefix): prefix=prefix[:-1]
 return prefix

def run_length_encode(text):
 result=[]
 for c in text:
  if result and result[-1][0]==c: result[-1]=(c,result[-1][1]+1)
  else: result.append((c,1))
 return result

def transpose(matrix):
